INSERT INTO `ofw` (`OFWId`, `FirstName`, `MiddleName`, `LastName`, `DOB`, `Sex`, `CivilStatus`, `Street`, `Barangay`, `City`, `Province`, `Zipcode`, `EducationalLevel`, `Skills`, `ContactNum`, `EmergencyContactNum`, `PassportNum`, `VISANum`, `OECNum`, `EmploymentStatus`, `DateAdded`, `PictureFace`, `AgencyID`, `LetterBody`) VALUES
(2371, 'Maria', 'Luna', 'Santos', '1992-05-10', 'Female', 'Single', 'Rizal St.', 'San Isidro', 'Daet', 'Camarines Norte', 4600, 'College', 'Nursing', 9171112233, 9172223344, 'P1234567A', 123456789, 12345678, 'Deployed', '2018-03-15 02:00:00', , 101, 'I am writing to express my interest in applying for an overseas employment opportunity through Global Workforce Solution. As a hardworking and dedicated individual, I am eager to bring my skills, professionalism, and strong work ethic to contribute positively to your partner employers abroad.\r\n\r\nI have gained relevant experience in [your field or position], and I am confident in my ability to perform well in a challenging international environment. I am highly adaptable, willing to learn, and committed to excellence in every task I undertake.\r\n\r\nI am particularly impressed with Global Workforce Solution\'s reputation for providing quality deployment services and supporting Filipino workers throughout the process. I believe that with your guidance and placement, I can pursue a meaningful and successful career abroad.\r\n\r\n');
